1	/* Tier-2 C-level fixture: 16x16x16 GEMM via RVV intrinsics, split across
2	 * the three handoff phases.
3	 *
4	 *   QEMU 1: init_matrices -- RVV vid.v + vadd.vx + vrem.vx fills A and B.
5	 *           V instructions retire just before the entry drain, exercising
6	 *           the plugin's HandoffSite translation-time PC capture (the
7	 *           old qemu_plugin_read_register("pc") path lagged for V).
8	 *   vsim:   vmatmul_kernel -- RVV outer-product GEMM (vle32 + vmacc.vx +
9	 *           vse32). V instructions also straddle the exit drain.
10	 *   QEMU 2: scalar_matmul_verify -- pure C reference recomputation, then
11	 *           cell-by-cell compare against vsim's C. Mismatch -> PASS=0.
12	 *
13	 * RVV shape
14	 *   VLEN=512, e32, LMUL=1 -> vlmax = 16 elements per V reg, exactly one
15	 *   row of a 16-wide matrix. The kernel runs N outer iterations (one per
16	 *   row of A), each accumulating into a single V register seeded to zero
17	 *   and storing it back as one row of C. No mask register, no tail policy
18	 *   subtlety: the vl set by vsetvli equals N for every iteration.
19	 *
20	 * Cross-phase memory survival (same convention as rt_c_matmul.c)
21	 *   Matrices sit in .bss. The "no redundant ELF reload" rule (vsim
22	 *   skips load_elf and QEMU 2 drops -kernel when --shared-mem-path is
23	 *   set) keeps phase-1 .bss writes intact through the shared
24	 *   memory-backend-file.
25	 */
26	#include "runtime/rt_c_helpers.h"
27	
28	#include <riscv_vector.h>
29	#include <stdint.h>
30	#include <stdio.h>
31	
32	#define N 16
33	
34	/* Repeat count for the vsim-phase kernel. The marked build (default,
35	 * GEMM_REPEAT=1) runs the GEMM once between the drain markers, behavior-
36	 * identical to a single matmul. The markerless twin (built with
37	 * -DHYBRID_MARKERLESS -DGEMM_REPEAT=K) drops the markers and runs K back-to-
38	 * back GEMMs, lengthening the instruction stream so the count-driven modes
39	 * (icount / bbv / slice) have a long, marker-free window to sample. Each
40	 * kernel call re-seeds its accumulator and overwrites C, so repeating is
41	 * idempotent -- the phase-3 scalar verify holds for any GEMM_REPEAT >= 1. */
42	#ifndef GEMM_REPEAT
43	#define GEMM_REPEAT 1
44	#endif
45	
46	static int32_t A[N * N];
47	static int32_t B[N * N];
48	static int32_t C[N * N];
49	
50	#define AT(M, i, j) ((M)[(i) *N + (j)])
51	
52	/* Vectorized init: one V register holds [0, 1, ..., N-1], reused across
53	 * rows. Per row i: A[i][:] = (vidx + i)   % 7, B[i][:] = (vidx + 3i) % 5.
54	 * vid.v writes unsigned lane indices; reinterpret to signed so the rest of
55	 * the math (and the int32_t* matrix pointers) stay in i32 land. */
56	static void init_matrices(void)
57	{
58	  size_t           vl     = __riscv_vsetvl_e32m1((size_t) N);
59	  const vuint32m1_t vidx_u = __riscv_vid_v_u32m1(vl);
60	  const vint32m1_t  vidx   = __riscv_vreinterpret_v_u32m1_i32m1(vidx_u);
61	
62	  for (int i = 0; i < N; i++) {
63	    vint32m1_t va = __riscv_vadd_vx_i32m1(vidx, i, vl);
64	    va            = __riscv_vrem_vx_i32m1(va, 7, vl);
65	    __riscv_vse32_v_i32m1(&AT(A, i, 0), va, vl);
66	
67	    vint32m1_t vb = __riscv_vadd_vx_i32m1(vidx, i * 3, vl);
68	    vb            = __riscv_vrem_vx_i32m1(vb, 5, vl);
69	    __riscv_vse32_v_i32m1(&AT(B, i, 0), vb, vl);
70	  }
71	}
72	
73	/* Outer-product RVV GEMM: for each row i of C, accumulate
74	 *   C[i][:] += A[i][k] * B[k][:]
75	 * using a single V register per row.
76	 *
77	 * noinline keeps the kernel a distinct symbol at -O1 so PC-range modes can
78	 * anchor on it, and keeps every kernel op inside the marker span (a call
79	 * cannot be reordered across the memory-clobbering enter/exit markers; see
80	 * runtime/rt_c_helpers.h cycle-attribution contract). */
81	static void __attribute__((noinline)) vmatmul_kernel(void)
82	{
83	  for (int i = 0; i < N; i++) {
84	    size_t     vl   = __riscv_vsetvl_e32m1((size_t) N);
85	    vint32m1_t vacc = __riscv_vmv_v_x_i32m1(0, vl);
86	    for (int k = 0; k < N; k++) {
87	      const int32_t  a_ik = AT(A, i, k);
88	      const vint32m1_t vb_k =
89	        __riscv_vle32_v_i32m1(&AT(B, k, 0), vl);
90	      vacc = __riscv_vmacc_vx_i32m1(vacc, a_ik, vb_k, vl);
91	    }
92	    __riscv_vse32_v_i32m1(&AT(C, i, 0), vacc, vl);
93	  }
94	}
95	
96	/* Pure scalar reference, independent of the RVV kernel above. */
97	static int scalar_matmul_verify(void)
98	{
99	  for (int i = 0; i < N; i++) {
100	    for (int j = 0; j < N; j++) {
101	      int32_t s = 0;
102	      for (int k = 0; k < N; k++)
103	        s += AT(A, i, k) * AT(B, k, j);
104	      if (AT(C, i, j) != s)
105	        return 0;
106	    }
107	  }
108	  return 1;
109	}
110	
111	int main(void)
112	{
113	  /* Phase 1 (QEMU 1): seed inputs only. */
114	  init_matrices();
115	
116	#ifndef HYBRID_MARKERLESS
117	  enter_vsim();
118	#endif
119	
120	  /* Phase 2 (vsim): RVV kernel only. No I/O permitted. */
121	  for (int rep = 0; rep < GEMM_REPEAT; rep++)
122	    vmatmul_kernel();
123	
124	#ifndef HYBRID_MARKERLESS
125	  exit_vsim();
126	#endif
127	
128	  /* Phase 3 (QEMU 2): scalar reference compare. */
129	  if (!scalar_matmul_verify()) {
130	    printf("rt_c_v_matmul: FAIL\n");
131	    fflush(stdout);
132	    return 1;
133	  }
134	  printf("rt_c_v_matmul: PASS\n");
135	  fflush(stdout);
136	  return 0;
137	}
